const KEY='sql-studio-v1';
const icons={db:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',book:'<path d="M12 5v15M12 5C7 2 2 4 2 4v15s5-2 10 1c5-3 10-1 10-1V4s-5-2-10 1Z"/>',case:'<path d="M8 5V3h8v2M4 5h16v16H4zM8 11h8M8 15h5"/>',code:'<path d="m4 5 6 7-6 7M13 19h7"/>',stats:'<path d="M5 20V11M12 20V4M19 20V8M3 21h19"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/>'};
Object.assign(icons,{menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',play:'<path d="m9 5 11 7-11 7Z"/>',check:'<path d="m5 12 4 4L19 6"/>',reset:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',table:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M10 10v10"/>',layers:'<path d="m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 17l10 5 10-5"/>',plan:'<rect x="9" y="3" width="6" height="5" rx="1"/><path d="M12 8v5M5 13h14M5 13v3m14-3v3"/><rect x="2" y="16" width="6" height="5" rx="1"/><rect x="16" y="16" width="6" height="5" rx="1"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>'});
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true,saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(e){storageOK=false}
if(!saved.stats||typeof saved.stats!=='object'||Array.isArray(saved.stats))saved.stats={};for(const [id,r] of Object.entries(saved.stats)){if(!lessons[+id]||!r||typeof r!=='object'){delete saved.stats[id];continue;}r.solved=[...new Set((Array.isArray(r.solved)?r.solved:[]).filter(v=>v===0||v===1))];}if(saved.version!==2&&saved.version!==3)Object.values(saved.stats||{}).forEach(r=>{if(r.solved?.length>=2)r.legacy=true});
let state={page:'practice',id:Number.isInteger(saved.id)&&lessons[saved.id]?saved.id:0,variant:0,query:'',hint:0,assisted:false,result:null,expected:null,feedback:null,busy:false,lessonTab:'understand',outputTab:'results',stats:saved.stats||{},history:saved.history||[],level:saved.level||'Beginner',pathGroup:-1,search:'',dataset:'shop',quizChoice:null,walkStep:0,walkResult:null,walkError:null,plan:null,caseId:null,planChoice:0,comparison:null,warehouseNode:'sources',warehouseTab:'map',menuOpen:false,practiceFocus:'learn'};
let worker,timer;const root=document.getElementById('app');
function record(id=state.id){return state.stats[id]||{attempts:0,correct:0,solved:[],last:0,errors:0,check:false}}
function mastered(id){const r=record(id);return r.solved.length>=2&&(r.check||r.legacy)}
function masteryCount(){return lessons.filter(l=>mastered(l.id)).length}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:2,id:state.id,stats:state.stats,history:state.history.slice(-200),level:state.level}))}catch(e){storageOK=false}}
function draftKey(){if(state.page==='lab')return 'sql-lab-script';return state.page==='playground'?'sql-playground-'+state.dataset:'sql-draft-'+state.id+'-'+state.variant}
function persistDraft(){try{sessionStorage.setItem(draftKey(),state.query);if(state.page==='lab')sessionStorage.setItem('sql-lab-dataset',state.dataset)}catch(e){}}
function scrollPractice(){if(typeof matchMedia==='function'&&matchMedia('(max-width:960px)').matches)document.querySelector('.practice-switch')?.scrollIntoView?.({block:'start',behavior:'instant'});}
function starter(id){return id===0?'SELECT \nFROM customers;':'-- Write your query here\n'}
function cancelWork(){worker?.terminate();clearTimeout(timer);state.busy=false}
function openLesson(id,variant){if(!lessons[id])return;cancelWork();state.id=id;state.variant=variant??(record(id).solved.includes(0)?1:0);state.page='practice';state.menuOpen=false;state.practiceFocus='learn';state.dataset=lessons[id].dataset;if(state.caseId!==null&&!caseStudyGroups[state.caseId].ids.includes(id))state.caseId=null;state.hint=0;state.assisted=false;state.feedback=null;state.result=null;state.plan=null;state.expected=null;state.outputTab='results';state.lessonTab='understand';state.quizChoice=null;state.walkStep=0;state.walkResult=null;state.walkError=null;state.query=starter(id);try{state.query=sessionStorage.getItem(draftKey())||state.query}catch(e){}save();render()}
state.dataset=lessons[state.id].dataset;state.variant=record().solved.includes(0)?1:0;state.query=starter(state.id);try{state.query=sessionStorage.getItem(draftKey())||state.query}catch(e){}
function table(result){if(!result)return `<div class="empty">${icon('table')}<strong>Your results go here</strong><span>Write a query and select Run query to see the rows.</span></div>`;return `<div class="scroll" tabindex="0" role="region" aria-label="Query results"><table><thead><tr>${result.columns.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${result.values.map(r=>`<tr>${r.map(v=>`<td>${v===null?'<em>NULL</em>':esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${result.values.length?'':'<div class="empty">No rows returned.</div>'}${result.columns.length>3?'<p class="tablescrollhint">Swipe across the table to see more columns.</p>':''}`}
function syntax(sql){const pattern=/(--[^\n]*|'(?:''|[^'])*'|\b(?:SELECT|FROM|WHERE|CREATE|ALTER|DROP|TABLE|TEMP|VIEW|INDEX|TRIGGER|INSERT|INTO|VALUES|UPDATE|SET|DELETE|BEGIN|COMMIT|ROLLBACK|SAVEPOINT|AFTER|OF|PRIMARY|KEY|CHECK|UNIQUE|NULL|AS|WITH|RECURSIVE|UNION|ALL|JOIN|LEFT|RIGHT|FULL|OUTER|INNER|CROSS|ON|GROUP|BY|HAVING|ORDER|ASC|DESC|LIMIT|CASE|WHEN|THEN|ELSE|END|OVER|PARTITION|ROWS|BETWEEN|PRECEDING|FOLLOWING|UNBOUNDED|CURRENT|ROW|AND|OR|NOT|IN|IS|NULL|EXISTS|DISTINCT|COUNT|SUM|AVG|MIN|MAX|COALESCE|NULLIF|ROUND|CAST|DATE|STRFTIME|JULIANDAY|SUBSTR|LOWER|UPPER|TRIM|ROW_NUMBER|RANK|DENSE_RANK|LAG|LEAD|FIRST_VALUE|LAST_VALUE)\b|\b\d+(?:\.\d+)?\b|[+*/%=<>!|-]+)/gi;let out='',last=0;for(const m of sql.matchAll(pattern)){out+=esc(sql.slice(last,m.index));const text=m[0],cls=text.startsWith('--')?'comment':text.startsWith("'")?'string':/^\d/.test(text)?'number':/^[+*/%=<>!|-]+$/.test(text)?'operator':/^(COUNT|SUM|AVG|MIN|MAX|COALESCE|NULLIF|ROUND|CAST|DATE|STRFTIME|JULIANDAY|SUBSTR|LOWER|UPPER|TRIM|ROW_NUMBER|RANK|DENSE_RANK|LAG|LEAD|FIRST_VALUE|LAST_VALUE)$/i.test(text)?'function':'keyword';out+=`<span class="${cls}">${esc(text)}</span>`;last=m.index+text.length;}return out+esc(sql.slice(last))+'\n'}
function schema(){const ds=datasetCatalog[state.dataset];return `<div class="schema"><label for="dataset">Database</label><select id="dataset">${Object.entries(datasetCatalog).map(([k,d])=>`<option value="${k}" ${k===state.dataset?'selected':''}>${d.name} · ${d.role}</option>`).join('')}</select><p class="note">${esc(ds.description)}</p><h4>Tables in this database</h4>${ds.tables.map(name=>`<details><summary>${icon('table')} ${name}</summary><div class="fields">${schemas[name].map(esc).join('\n')}</div><button class="textbutton" data-action="inspect" data-table="${name}">Preview rows →</button></details>`).join('')}<small>Fictional teaching data · UTC timestamps · SQLite</small></div>`}
function quiz(){const q=quizFor(state.id),r=record(),answered=state.quizChoice!==null;return `<div class="quiz"><h3>Check your intuition</h3><p>${esc(q.q)}</p><div class="quizoptions">${q.options.map((o,i)=>`<button data-action="quiz" data-choice="${i}" class="${answered&&(i===q.correct?'right':i===state.quizChoice?'wrong':'')}">${String.fromCharCode(65+i)}<span>${esc(o)}</span></button>`).join('')}</div>${answered?`<p class="quizfeedback" role="status">${state.quizChoice===q.correct?'✓ Exactly.':'Keep this distinction in mind.'} ${esc(q.why)}</p>`:r.check?'<p class="note">✓ Concept check passed. Revisit it anytime.</p>':''}</div>`}
function walkthrough(){const steps=stepsFor(state.id),s=steps[state.walkStep];return `<div class="walk"><p class="note">A curated walkthrough of the reference query. These stages do not explain arbitrary SQL you type.</p><div class="steprail">${steps.map((s,i)=>`<button data-action="walkstep" data-step="${i}" class="${i===state.walkStep?'active':''}" aria-label="Step ${i+1}: ${esc(s.title)}">${i+1}</button>`).join('')}</div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><pre class="sqlblock">${syntax(s.query)}</pre><button class="small" data-action="walkrun" ${state.busy?'disabled':''}>${icon('play')} Run this stage</button>${state.walkError?`<p class="note errorText">${esc(state.walkError)}</p>`:''}${state.walkResult?`<div class="walkresult"><p class="note">${state.walkResult.total} actual rows · ${state.walkResult.total>200?'first 200 shown':''}</p>${table(state.walkResult)}</div>`:''}<div class="walknav"><button class="textbutton" data-action="walkstep" data-step="${Math.max(0,state.walkStep-1)}" ${state.walkStep===0?'disabled':''}>← Previous</button><button class="textbutton" data-action="walkstep" data-step="${Math.min(steps.length-1,state.walkStep+1)}" ${state.walkStep===steps.length-1?'disabled':''}>Next stage →</button></div></div>`}
function lessonPanel(){const l=lessons[state.id],t=l.tasks[state.variant];return `<section class="lesson panel"><div class="meta">${String(l.group+1).padStart(2,'0')} / ${groups[l.group]} · ${datasetCatalog[l.dataset].name}</div><h2>${l.id===42?'Rolling averages, without losing the rows':esc(l.title)}</h2><div class="lessontabs tabs">${[['understand','Understand'],['challenge','Challenge'],['walkthrough','Walkthrough']].map(([key,text])=>`<button class="${state.lessonTab===key?'active':''}" data-action="lessontab" data-tab="${key}">${text}</button>`).join('')}</div>${l.mode==='lab'?'<p class="labnotice">Disposable lab · include setup and a final SELECT in one script. Each run resets the data.</p>':''}${state.lessonTab==='understand'?`<p class="concept">${esc(l.concept)}</p><div class="insight"><h3>${l.id===42?'Rows ≠ days':'Keep this in mind'}</h3><p>${esc(l.trap)}</p></div>${l.dialectReference?`<details class="referenceonly"><summary>SQL Server reference · not executable here</summary><pre class="sqlblock">${syntax(l.dialectReference)}</pre></details>`:''}<details class="example"><summary>See a runnable example</summary><pre class="sqlblock">${syntax(l.example)}</pre><button class="textbutton" data-action="example">Open in editor →</button><p class="note">Opening the example makes this a guided attempt.</p></details>`:state.lessonTab==='walkthrough'?walkthrough():`<p class="note">${esc(l.grain)} Think through the output before writing the query.</p>`}<div class="task"><div class="taskhead"><h3>Your task</h3><span>${l.difficulty} · ${state.variant+1} / 2</span></div><p>${esc(t.prompt)}</p><div class="tasktools"><button class="textbutton" data-action="variant" data-variant="0" aria-pressed="${state.variant===0}">Challenge 1</button><button class="textbutton" data-action="variant" data-variant="1" aria-pressed="${state.variant===1}">Challenge 2</button><button class="textbutton" data-action="hint">${state.hint?'Next hint':'Need a hint?'}</button></div>${state.hint?l.hints.slice(0,Math.min(state.hint,2)).map((h,i)=>`<p class="hinttext"><strong>${i+1}.</strong> ${esc(h)}</p>`).join(''):''}${state.hint>=3?`<pre class="sqlblock">${syntax(t.answer)}</pre><button class="textbutton" data-action="solution">Open solution →</button>`:''}${state.assisted?'<div class="note">Guided attempt · try a fresh attempt for independent credit.</div>':''}<details class="schema-disclosure"><summary>${icon('db')} Database & table schema <span>${datasetCatalog[state.dataset].name}</span></summary>${schema()}</details></div><button class="primary mobile-write" data-action="practicefocus" data-focus="write">Write your SQL ${icon('arrow')}</button>${state.lessonTab!=='walkthrough'?quiz():''}<div class="lessonfooter"><button class="textbutton" data-action="previous">← Previous lesson</button><button class="textbutton" data-action="skip">Next lesson →</button></div></section>`}
function feedback(){const f=state.feedback;if(!f)return '';return `<div class="feedback ${f.ok?'':'error'}" role="status"><strong>${esc(f.title)}</strong><p>${esc(f.message)}</p><div class="actions">${f.ok?`<button class="primary small" data-action="next">${record().solved.length>=2&&!mastered(state.id)?'Finish concept check':mastered(state.id)?'Next concept':'Try challenge '+(2-state.variant)} →</button>`:`<button class="small" data-action="hint">Give me a hint</button>${record().errors>=2?'<button class="small" data-action="easier">Revisit a prerequisite</button>':''}`}<button class="textbutton small" data-action="again">Fresh attempt</button></div></div>`}
function editorPanel(){const lab=state.page==='lab'||state.page==='practice'&&lessons[state.id].mode==='lab';const result=state.outputTab==='expected'?state.expected:state.outputTab==='plan'?state.plan:state.result;return `<section class="editorzone" aria-label="SQL workspace" aria-busy="${state.busy}"><div class="panel editorpanel"><div class="editorhead"><strong>${icon('code')} ${lab?'SQL script':'Query editor'}</strong><span>SQLite <span class="note">${lab?'· disposable writes':'· read-only'}</span></span></div><div class="editor"><div class="numbers" aria-hidden="true">${state.query.split('\n').map((_,i)=>i+1).join('\n')}</div><div class="codearea"><pre id="highlight" aria-hidden="true">${syntax(state.query)}</pre><textarea id="query" autocorrect="off" aria-label="SQL query editor" spellcheck="false" autocapitalize="off" autocomplete="off" wrap="off">${esc(state.query)}</textarea></div></div><div class="toolbar"><button class="primary" data-action="run" ${state.busy?'disabled':''}>${icon('play')}${state.busy?'Running…':'Run query'}</button>${state.page==='practice'?`<button class="outline" data-action="check" ${state.busy?'disabled':''}>${icon('check')} Check answer</button>`:''}<button class="textbutton reset" data-action="reset">${icon('reset')} Reset</button></div><div class="editornote"><span class="keyboardhint">⌘ / Ctrl + Enter runs · ${lab?'Every run starts fresh · end with SELECT':state.page==='practice'?'Shift + Enter with ⌘ / Ctrl checks your answer':'Explore without grades'}</span><span class="touchhint">${lab?'Include setup and a final SELECT.':state.page==='practice'?'Run to explore. Check answer to validate.':'Run a query to explore the data.'}</span></div></div>${feedback()}<div class="panel outputpanel"><div class="tabs outputtabs"><button data-action="output" data-tab="results" class="${state.outputTab==='results'?'active':''}">Results</button>${state.page==='practice'?`<button data-action="output" data-tab="expected" class="${state.outputTab==='expected'?'active':''}">Expected</button>`:''}<button data-action="plan" class="${state.outputTab==='plan'?'active':''}" ${state.busy?'disabled':''}>Query plan</button></div><div class="results">${state.outputTab==='expected'&&!state.expected?'<div class="empty">Check an answer to enable result comparison.</div>':table(result)}${result?`<div class="resultfooter" role="status" aria-live="polite">${result.total??result.values.length} rows${result.total>200?' · first 200 shown':''}</div>`:''}${state.outputTab==='plan'?'<p class="note">SCAN reads rows; SEARCH uses a lookup. Small teaching tables may favor scans. This is a real SQLite plan.</p>':''}</div></div>${state.page==='practice'?'<p class="note resultnote">Check answer validates column names, values, duplicates, requested ordering, and a changed-data fixture. Run query is ungraded.</p>':''}</section>`}
function practice(){return `<div class="lesson-context"><span>Lesson ${courseOrder.indexOf(state.id)+1} of ${lessons.length}</span><span>${record().solved.length} / 2 independent solves ${record().check?'· Concept check passed':''}</span></div><div class="practice-switch" aria-label="Practice view">${[['learn','book','Understand'],['write','code','Write SQL'],['results','table','Results']].map(([key,i,label])=>`<button data-action="practicefocus" data-focus="${key}" aria-pressed="${state.practiceFocus===key}">${icon(i)}${label}</button>`).join('')}</div><div class="workspace practice-workspace focus-${state.practiceFocus}">${lessonPanel()}${editorPanel()}</div><div class="adapt">${icon('book')}<strong>Ready when you are</strong><span>${record().errors>=2?'A prerequisite or walkthrough can help with this concept.':mastered(state.id)?'Two independent solves and a concept check. This concept is mastered.':'Practice variants and a quick concept check build real understanding.'}</span><button class="textbutton" data-action="next" aria-label="Continue practice">→</button></div>`}
function learningPath(){const matching=courseOrder.map(id=>lessons[id]).filter(l=>(state.pathGroup<0||l.group===state.pathGroup)&&(`${l.title} ${groups[l.group]} ${datasetCatalog[l.dataset].name}`).toLowerCase().includes(state.search.toLowerCase()));return `<div class="courseintro"><div><h2>${lessons.length} lessons. From syntax to sound analysis.</h2><p>${lessons.length*2} challenges across ${groups.length} modules. Start at your level; every lesson is open.</p></div><div class="actions"><select id="level" aria-label="Choose a starting level"><option>Choose a starting level</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div></div><div class="pathcontrols"><input id="lessonsearch" type="search" aria-label="Search lessons" placeholder="Find a concept, e.g. retention" value="${esc(state.search)}"><button class="textbutton" data-action="module" data-group="-1">All modules</button></div>${groups.map((g,i)=>{const ls=matching.filter(l=>l.group===i);return ls.length?`<section class="pathgroup"><div class="grouptitle"><span>${String(i+1).padStart(2,'0')}</span><div><h2>${g}</h2><p>${moduleDescriptions[i]}</p></div><small>${ls.length} lessons</small></div>${ls.map(l=>`<div class="pathrow"><span class="num">${String(courseOrder.indexOf(l.id)+1).padStart(2,'0')}</span><div class="title">${esc(l.title)}<small>${datasetCatalog[l.dataset].name} · ${l.difficulty}</small></div><span class="state ${mastered(l.id)?'done':''}">${mastered(l.id)?'✓ Mastered':record(l.id).solved.length?record(l.id).solved.length+' / 2 solves':'Ready to learn'}</span><button class="textbutton" data-action="lesson" data-id="${l.id}" aria-label="Open ${esc(l.title)}">Open →</button></div>`).join('')}</section>`:''}).join('')}${!matching.length?'<div class="empty">No matching lessons. Try a broader search or select All modules.</div>':''}`}
function cases(){return `<div class="caseintro"><h2>Build the data. Explain the result.</h2><button class="outline" data-action="nav" data-page="warehouse">Explore the warehouse blueprint →</button><p>Each case study is a sequence of lessons on one fictional product. Define the metric, inspect the grain, write the query, then test the result.</p></div>${caseStudyGroups.map((c,i)=>`<section class="caseblock"><div class="caselead"><span class="caseindex">0${i+1}</span><div><div class="meta">${datasetCatalog[c.dataset].name} · ${datasetCatalog[c.dataset].role}</div><h2>${c.title}</h2><p>${c.description}</p><button class="outline" data-action="lesson" data-id="${c.ids[0]}" data-case="${i}">Start case study →</button></div></div><div class="casesteps">${c.ids.map((id,j)=>`<button data-action="lesson" data-id="${id}" data-case="${i}"><span>${j+1}</span><div>${esc(lessons[id].title)}<small>${mastered(id)?'✓ Mastered':'Open lesson →'}</small></div></button>`).join('')}</div></section>`).join('')}<p class="note">All names, records, and model rates are synthetic teaching material. These are independent case studies, not official company datasets.</p>`}
function playground(){return `<div class="workspace"><section class="panel lesson"><div class="meta">Ungraded exploration</div><h2>Your own questions, real SQL.</h2><p>Choose a teaching database, inspect its rows, and test an idea. Every execution starts with fresh data.</p><div class="insight"><h3>One query at a time</h3><p>SELECT, WITH, and EXPLAIN are supported. Queries stop after three seconds; results display up to 200 rows.</p></div>${schema()}<div class="quiz"><h3>Try a starting question</h3>${[0,1,2].map((n)=>`<button class="textbutton preset" data-action="preset" data-preset="${n}">${esc(presets()[n].label)} →</button>`).join('')}</div></section>${editorPanel()}</div>`}
function presets(){return {integration:[{label:'Compare source and landed counts',query:lessons[76].example},{label:'Resolve CRM + ERP customer attributes',query:lessons[77].example},{label:'Inspect the field catalog',query:'SELECT * FROM warehouse_catalog;'}],warehouse:[{label:'Profile raw customer versions',query:lessons[69].tasks[0].answer},{label:'Explore the sales fact',query:lessons[72].tasks[0].answer},{label:'Customer report',query:lessons[73].tasks[0].answer}],lab:[{label:'Read the lab inventory',query:'SELECT * FROM lab_items;'},{label:'Inspect audit records',query:'SELECT * FROM lab_audit;'},{label:'Find higher-priced items',query:'SELECT * FROM lab_items WHERE price>40;'}],shop:[{label:'Most expensive products',query:'SELECT name,price FROM products ORDER BY price DESC;'},{label:'Paid revenue',query:"SELECT SUM(o.quantity*p.price) AS revenue FROM orders o JOIN products p ON p.id=o.product_id WHERE o.status='paid';"},{label:'Customers without orders',query:'SELECT c.name FROM customers c WHERE NOT EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=c.id);'}],stream:[{label:'Daily active viewers',query:lessons[45].tasks[0].answer},{label:'Rolling observed-row average',query:lessons[42].tasks[0].answer},{label:'Exact-day D7 retention',query:lessons[47].tasks[1].answer}],social:[{label:'Latest version of each event',query:lessons[44].tasks[0].answer},{label:'Ordered conversion funnel',query:lessons[46].tasks[0].answer},{label:'Session counts',query:lessons[48].tasks[0].answer}],ai:[{label:'Successful usage cost by model',query:lessons[51].tasks[0].answer},{label:'Invoice reconciliation gaps',query:lessons[50].tasks[1].answer},{label:'Safe account-level summaries',query:lessons[49].tasks[0].answer}]}[state.dataset]}
function progress(){const vals=Object.values(state.stats),attempts=vals.reduce((a,s)=>a+s.attempts,0),correct=vals.reduce((a,s)=>a+s.correct,0),next=recommendation();return `<h2>Understanding is the goal.</h2><p class="note">Mastery = two independent challenge solves plus a concept check. Completed lessons from the original version keep their mastery.</p><div class="stats"><div><strong>${masteryCount()} / ${lessons.length}</strong><small>Concepts mastered</small></div><div><strong>${attempts}</strong><small>Answer checks</small></div><div><strong>${correct}</strong><small>Correct checks</small></div></div><div class="progresslist">${groups.map((g,i)=>{const ls=lessons.filter(l=>l.group===i),m=ls.filter(l=>mastered(l.id)).length;return `<div class="progressrow"><span>${g}</span><div class="bar"><i style="width:${100*m/ls.length}%"></i></div><small>${m} / ${ls.length}</small></div>`}).join('')}</div><div class="nextup"><div><h3>Recommended next</h3><p>${esc(lessons[next].title)}</p><p class="note">${record(next).errors>=2?'Recent mistakes make this a useful concept to revisit.':reviewDue().some(l=>l.id===next)?'This mastered concept is due for spaced review.':'Strengthen this concept, then move forward.'}</p></div><button class="outline" data-action="recommend">Practice →</button></div><div class="pathgroup"><h3>Recent practice</h3>${state.history.length?state.history.slice(-8).reverse().filter(h=>lessons[h.id]).map(h=>`<div class="pathrow"><div class="title">${esc(lessons[h.id].title)}<small>${new Date(h.time).toLocaleString()}</small></div><span class="state ${h.ok?'done':''}">${h.ok?(h.guided?'Guided solve':'Independent'):'Revisit'}</span></div>`).join(''):'<p class="note">Check your first answer to start tracking practice.</p>'}</div><p class="note ${storageOK?'':'errorText'}">${storageOK?'Progress stays in this browser and does not sync across devices.':'Storage is unavailable. Progress lasts for this session only.'}</p><div class="actions"><button data-action="export">Export progress</button><label class="importbutton">Import progress<input type="file" id="import" accept="application/json" hidden></label><button class="textbutton" data-action="clear">Reset progress</button></div>`}
function reviewDue(){return lessons.filter(l=>mastered(l.id)&&Date.now()-record(l.id).last>86400000)}
function recommendation(){const weak=courseOrder.map(i=>lessons[i]).filter(l=>record(l.id).attempts&&!mastered(l.id));if(weak.some(l=>record(l.id).errors>=2))return weak.sort((a,b)=>record(b.id).errors-record(a.id).errors)[0].id;const due=reviewDue();if(due.length)return due.sort((a,b)=>record(a.id).last-record(b.id).last)[0].id;if(weak.length)return weak[0].id;const at=courseOrder.indexOf(state.id);return courseOrder.slice(at).find(id=>!mastered(id))??courseOrder.find(id=>!mastered(id))??state.id}
function nextInPath(id,dir=1){const order=state.caseId!==null?caseStudyGroups[state.caseId].ids:courseOrder;const idx=order.indexOf(id);return order[Math.max(0,Math.min(order.length-1,idx+dir))]}
const navItems=[['path','book','Learn'],['cases','layers','Projects'],['lab','code','Engineering lab'],['plans','plan','Query plans'],['playground','db','Playground'],['progress','stats','Progress'],['dialects','globe','Dialect guide']];
function activePage(page){return state.page===page||page==='path'&&state.page==='practice'||page==='cases'&&state.page==='warehouse';}
function render(){const titles={warehouse:['Warehouse blueprint','Explore the layers, trace the fields, and test the rules.'],lab:['Engineering lab','Create, change, and inspect a fresh practice database.'],plans:['Query plan lab','Compare access paths and verify the results.'],dialects:['SQL dialect guide','See what runs here and how syntax changes across engines.'],practice:['Your SQL workspace','Understand the idea. Write a query. Learn from the result.'],path:['Your learning path','From your first SELECT to trusted analytics and warehouse design.'],cases:['Put SQL to work','Guided projects with realistic questions and original teaching data.'],playground:['SQL playground','Choose a database and explore your own questions.'],progress:['Your progress','Build understanding through practice, concept checks, and review.']};const [title,sub]=titles[state.page];root.innerHTML=`<a class="skiplink" href="#main-content">Skip to content</a><header class="mobilebar"><div class="brand"><span class="brandmark">${icon('db')}</span>SQL Studio</div><button class="iconbutton menutoggle" data-action="menu" aria-label="Open navigation" aria-expanded="${state.menuOpen}" aria-controls="site-sidebar">${icon('menu')}</button></header>${state.menuOpen?'<button class="drawer-backdrop" data-action="closemenu" aria-label="Close navigation"></button>':''}<aside id="site-sidebar" class="sidebar ${state.menuOpen?'is-open':''}" ${state.menuOpen?'role="dialog" aria-modal="true"':''} aria-label="Navigation and course modules"><div class="brand"><span class="brandmark">${icon('db')}</span>SQL Studio<button class="iconbutton menuclose" data-action="closemenu" aria-label="Close navigation">${icon('close')}</button></div><div class="nav-label">YOUR WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navItems.map(([page,i,label])=>`<button data-action="nav" data-page="${page}" ${activePage(page)?'aria-current="page"':''} class="${activePage(page)?'active':''}">${icon(i)}${label}</button>`).join('')}</nav><details class="module-disclosure" ${state.page==='path'?'open':''}><summary>Course modules</summary><div class="courseoutline">${groups.map((g,i)=>`<button data-action="module" data-group="${i}" class="${state.page==='practice'&&lessons[state.id].group===i||state.page==='path'&&state.pathGroup===i?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${esc(g)}</button>`).join('')}</div></details><div class="sidefoot"><div><strong>${masteryCount()}</strong> of ${lessons.length} mastered</div><div class="bar"><i style="width:${100*masteryCount()/lessons.length}%"></i></div><span>${storageOK?'Progress saved in this browser':'Session-only progress'}</span></div></aside><main id="main-content" class="main" tabindex="-1"><header class="header"><div><div class="eyebrow">LEARN BY DOING</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${state.page!=='practice'?`<button class="primary continue" data-action="recommend">Continue learning ${icon('arrow')}</button>`:''}</header>${state.page==='practice'?practice():state.page==='path'?learningPath():state.page==='cases'?cases():state.page==='warehouse'?warehouseProject():state.page==='lab'?engineeringLab():state.page==='plans'?planLab():state.page==='dialects'?dialects():state.page==='playground'?playground():progress()}</main><nav class="bottomnav" aria-label="Mobile navigation">${[['path','book','Learn'],['cases','layers','Projects'],['resume','code','Practice'],['progress','stats','Progress']].map(([page,i,label])=>`<button data-action="${page==='resume'?'resume':'nav'}" ${page==='resume'?'':`data-page="${page}"`} ${state.page==='practice'&&page==='resume'||state.page===page||state.page==='warehouse'&&page==='cases'?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</nav>`;}
function execute(mode='run',override=null){if(state.busy)return;persistDraft();state.busy=true;state.feedback=null;state.outputTab=mode==='plan'?'plan':'results';if(mode==='check')state.expected=null;render();const l=lessons[state.id],t=l.tasks[state.variant],graded=mode==='check'&&state.page==='practice',guided=state.assisted,id=state.id,variant=state.variant;worker=new Worker('engine.js');
 const finish=()=>{clearTimeout(timer);worker.terminate();state.busy=false};
 const fail=msg=>{finish();if(mode!=='walk'&&state.page==='practice')state.practiceFocus='results';if(mode==='walk'){state.walkError=msg;state.walkResult=null}else{state.result=null;state.feedback={ok:false,title:'Let’s refine the query.',message:msg};if(graded)update(false,guided,id,variant)}render();if(mode!=='walk')scrollPractice()};
 worker.onmessage=({data})=>{if(data.ready)return;if(data.error){fail(data.error);return}finish();if(data.comparison){state.comparison={outputs:data.comparison,equivalent:data.equivalent};render();return;}if(mode==='walk'){state.walkResult={...data.result,total:data.total};state.walkError=null;render();return}if(state.page==='practice')state.practiceFocus='results';if(mode==='plan')state.plan={...data.result,total:data.total};else state.result={...data.result,total:data.total};if(data.grade){update(data.grade.ok,guided,id,variant);state.expected=data.expected;state.feedback={ok:data.grade.ok,title:data.grade.ok?(guided?'Good guided practice.':mastered(id)?'Concept mastered.':'Your logic checks out.'):'Let’s refine the answer.',message:data.grade.ok?(guided?'You solved it with support. Start a fresh attempt to build independent mastery.':'Passed the visible data and a changed-data check. '+(record(id).solved.length>=2&&!mastered(id)?'Complete the concept check to finish this lesson.':'Try the next challenge when you’re ready.')):data.grade.message}}else if(mode!=='check')state.feedback=null;render();scrollPractice()};
 worker.onerror=()=>fail('The SQL engine could not start. Refresh and try again.');timer=setTimeout(()=>fail('Query exceeded the three-second limit. Check for unbounded recursion or a large cross join. Try a smaller query.'),3000);
 worker.postMessage({seed,query:override||state.query,answer:graded?t.answer:null,ordered:t.ordered,explain:mode==='plan',mutation:graded?fixtureMutation:null,allowWrites:state.page==='lab'||state.page==='practice'&&l.mode==='lab',validate:graded?t.validate:null,required:graded?t.required:null,compare:mode==='compare'?planComparisons[state.planChoice].cases:null});}
function update(ok,guided,id,variant){const r=record(id);r.attempts++;r.correct+=ok?1:0;r.errors=ok?0:r.errors+1;r.last=Date.now();if(ok&&!guided&&!r.solved.includes(variant))r.solved.push(variant);state.stats[id]=r;state.history.push({id,variant,ok,guided,time:Date.now()});save()}
function toast(message){const t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=message;document.body.append(t);setTimeout(()=>t.remove(),4000)}
function nav(page){state.menuOpen=false;cancelWork();persistDraft();state.page=page;state.caseId=null;state.feedback=null;state.result=null;state.plan=null;state.expected=null;state.outputTab='results';if(page==='lab'){state.dataset='lab';state.query=lessons[59].example;try{const labDataset=sessionStorage.getItem('sql-lab-dataset');if(datasetCatalog[labDataset])state.dataset=labDataset;state.query=sessionStorage.getItem(draftKey())||state.query}catch(e){}}if(page==='playground'){state.query='SELECT * FROM '+datasetCatalog[state.dataset].tables[0]+';';try{state.query=sessionStorage.getItem(draftKey())||state.query}catch(e){}}render()}
function resetAttempt(){state.practiceFocus='write';state.hint=0;state.assisted=false;state.query=starter(state.id);state.result=null;state.feedback=null;state.expected=null;state.outputTab='results';state.lessonTab='challenge';persistDraft();render();scrollPractice()}
root.addEventListener('input',e=>{if(e.target.id==='query'){state.query=e.target.value;document.querySelector('.numbers').textContent=state.query.split('\n').map((_,i)=>i+1).join('\n');document.getElementById('highlight').innerHTML=syntax(state.query);persistDraft()}if(e.target.id==='lessonsearch'){const pos=e.target.selectionStart;state.search=e.target.value;render();const input=document.getElementById('lessonsearch');input.focus();try{input.setSelectionRange(pos,pos)}catch(e){}}});
root.addEventListener('toggle',e=>{if(e.target.classList?.contains('example')&&e.target.open)state.assisted=true},true);
root.addEventListener('scroll',e=>{if(e.target.id==='query'){const h=document.getElementById('highlight');h.scrollTop=e.target.scrollTop;h.scrollLeft=e.target.scrollLeft;document.querySelector('.numbers').scrollTop=e.target.scrollTop}},true);
root.addEventListener('change',async e=>{if(e.target.id==='planchoice'){state.planChoice=Number(e.target.value);state.comparison=null;render();}if(e.target.id==='level'){state.level=e.target.value;if(['Beginner','Intermediate','Advanced'].includes(state.level))openLesson({Beginner:0,Intermediate:14,Advanced:21}[state.level]);}if(e.target.id==='dataset'){persistDraft();const key=e.target.value;if(state.page==='playground'||state.page==='lab'){state.dataset=key;state.query='SELECT * FROM '+datasetCatalog[key].tables[0]+';';state.result=null;try{state.query=sessionStorage.getItem(draftKey())||state.query}catch(e){}render()}else openLesson(courseOrder.find(id=>lessons[id].dataset===key));}if(e.target.id==='import'){try{const data=JSON.parse(await e.target.files[0].text());if(!data.stats||typeof data.stats!=='object'||Array.isArray(data.stats))throw Error('Invalid progress file.');const clean={};Object.entries(data.stats).forEach(([id,r])=>{if(!lessons[Number(id)]||!Array.isArray(r.solved))return;clean[id]={attempts:Math.max(0,Number(r.attempts)||0),correct:Math.max(0,Number(r.correct)||0),solved:[...new Set(r.solved.filter(x=>x===0||x===1))],last:Number(r.last)||0,errors:Math.max(0,Number(r.errors)||0),check:r.check===true,legacy:r.legacy===true||data.version!==2&&r.solved.length>=2}});state.stats=clean;state.history=Array.isArray(data.history)?data.history.filter(h=>lessons[h.id]&&typeof h.ok==='boolean').slice(-200):[];save();render();toast('Progress imported.')}catch(err){toast('Could not import progress: '+err.message)}}});
root.addEventListener('keydown',e=>{if(state.menuOpen){if(e.key==='Escape'){e.preventDefault();state.menuOpen=false;render();document.querySelector('.menutoggle')?.focus?.();return;}if(e.key==='Tab'){const controls=[...(document.querySelectorAll?.('#site-sidebar button, #site-sidebar summary')||[])];const first=controls[0],last=controls.at(-1);if(first&&last&&((e.shiftKey&&document.activeElement===first)||(!e.shiftKey&&document.activeElement===last))){e.preventDefault();(e.shiftKey?last:first).focus();}}}if(e.target.id!=='query')return;if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)){e.preventDefault();execute(e.shiftKey&&state.page==='practice'?'check':'run')}if(e.key==='Tab'){e.preventDefault();e.target.setRangeText('  ',e.target.selectionStart,e.target.selectionEnd,'end');e.target.dispatchEvent(new Event('input',{bubbles:true}))}});
root.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(state.busy&&!['nav','module','lesson','menu','closemenu','practicefocus'].includes(a))return;
 if(a==='menu'){state.menuOpen=!state.menuOpen;render();document.querySelector('.menuclose')?.focus?.();}else if(a==='closemenu'){state.menuOpen=false;render();document.querySelector('.menutoggle')?.focus?.();}else if(a==='resume')openLesson(state.id);else if(a==='practicefocus'){persistDraft();state.practiceFocus=b.dataset.focus;render();scrollPractice();}else if(a==='nav')nav(b.dataset.page);else if(a==='module'){state.pathGroup=Number(b.dataset.group);state.search='';nav('path')}
 else if(a==='lesson'){state.caseId=b.dataset.case===undefined?null:Number(b.dataset.case);openLesson(Number(b.dataset.id));}else if(a==='recommend')openLesson(recommendation());
 else if(a==='warehousenode'){state.warehouseNode=b.dataset.node;render();}else if(a==='warehousetab'){state.warehouseTab=b.dataset.tab;render();}else if(a==='compare')execute('compare');else if(a==='labpreset'){persistDraft();const preset=lessons[Number(b.dataset.id)];state.dataset=preset.dataset;state.query=preset.example;state.result=null;state.plan=null;state.feedback=null;persistDraft();render();}else if(a==='run')execute();else if(a==='check')execute('check');else if(a==='plan')execute('plan');
 else if(a==='inspect')execute('run','SELECT * FROM '+b.dataset.table+';');
 else if(a==='lessontab'){state.lessonTab=b.dataset.tab;if(state.lessonTab==='walkthrough')state.assisted=true;render()}
 else if(a==='walkstep'){state.walkStep=Number(b.dataset.step);state.walkResult=null;state.walkError=null;render()}
 else if(a==='walkrun')execute('walk',stepsFor(state.id)[state.walkStep].query);
 else if(a==='output'){state.outputTab=b.dataset.tab;if(state.outputTab==='expected'&&state.expected)state.assisted=true;render()}
 else if(a==='hint'){state.practiceFocus='learn';state.hint=Math.min(3,state.hint+1);state.assisted=true;render()}
 else if(a==='example'||a==='solution'){state.query=(a==='example'?lessons[state.id].example:lessons[state.id].tasks[state.variant].answer)+';';state.assisted=true;state.practiceFocus='write';persistDraft();render();scrollPractice()}
 else if(a==='variant'){persistDraft();openLesson(state.id,Number(b.dataset.variant))}
 else if(a==='quiz'){state.quizChoice=Number(b.dataset.choice);const r=record();if(state.quizChoice===quizFor(state.id).correct){r.check=true;r.last=Date.now()}else r.errors++;state.stats[state.id]=r;save();render()}
 else if(a==='next'){if(record().solved.length>=2&&!mastered(state.id)){state.lessonTab='understand';state.practiceFocus='learn';render();document.querySelector('.quiz')?.scrollIntoView?.({behavior:'smooth',block:'center'})}else if(mastered(state.id))openLesson(nextInPath(state.id));else openLesson(state.id,1-state.variant)}
 else if(a==='skip')openLesson(nextInPath(state.id));else if(a==='previous')openLesson(nextInPath(state.id,-1));
 else if(a==='easier'){const p=lessons[state.id].prereq?.find(id=>!mastered(id))??lessons[state.id].prereq?.[0]??nextInPath(state.id,-1);openLesson(p)}
 else if(a==='reset'){if(state.page==='lab')state.dataset='lab';state.query=state.page==='lab'?lessons[59].example:state.page==='playground'?'SELECT * FROM '+datasetCatalog[state.dataset].tables[0]+';':starter(state.id);state.result=null;state.plan=null;state.feedback=null;persistDraft();render()}
 else if(a==='again')resetAttempt();else if(a==='preset'){state.query=presets()[Number(b.dataset.preset)].query;state.result=null;persistDraft();render()}
 else if(a==='export'){const blob=new Blob([JSON.stringify({version:2,exported_at:new Date().toISOString(),id:state.id,stats:state.stats,history:state.history},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download='sql-studio-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
 else if(a==='clear'){const d=document.createElement('dialog');d.innerHTML='<h2>Start a fresh learning path?</h2><p>This resets practice history and mastery in this browser. Export your progress first to keep a copy.</p><div class="actions"><button id="cancelclear">Keep progress</button><button class="primary" id="confirmclear">Reset progress</button></div>';document.body.append(d);d.showModal();d.querySelector('#cancelclear').onclick=()=>{d.close();d.remove()};d.querySelector('#confirmclear').onclick=()=>{state.stats={};state.history=[];save();d.close();d.remove();openLesson(0)};d.oncancel=()=>d.remove()}
});if(typeof SQL_STUDIO_EDITORIAL==='undefined'||!SQL_STUDIO_EDITORIAL)render();
function engineeringLab(){return `<div class="workspace"><section class="panel lesson"><div class="meta">Disposable database · ungraded lab</div><h2>Learn what a database can do.</h2><p>Create an object, change rows, inspect the result. Each run recreates all teaching tables in memory, and no change survives the run.</p><div class="insight"><h3>Write a complete script</h3><p>Include CREATE/INSERT/UPDATE and a final SELECT in one run. To inspect an index, end with SELECT and choose Query plan. Limit: 60 statements and three seconds.</p></div><details class="experiment-picker"><summary>Choose a working experiment</summary>${[58,59,60,61,62,63,64,66,70,71,80,82,84,85,87].map(id=>`<button class="preset textbutton" data-action="labpreset" data-id="${id}">${esc(lessons[id].title)} →</button>`).join('')}</details><h3 class="labheading">Want guided challenges?</h3><p class="note">The Database engineering and Warehouse modules check your result and the required objects.</p><button class="outline small" data-action="module" data-group="7">Open engineering lessons →</button>${schema()}</section>${editorPanel()}</div>`}
function planLab(){const p=planComparisons[state.planChoice],c=state.comparison;return `<div class="courseintro"><div><h2>Make a hypothesis. Inspect the evidence.</h2><p>A SCAN and a SEARCH are access strategies, not a measured performance score. These examples use tiny data; do not infer production latency from them.</p></div></div><div class="plancontrols"><select id="planchoice" aria-label="Choose plan comparison">${planComparisons.map((p,i)=>`<option value="${i}" ${i===state.planChoice?'selected':''}>${p.title}</option>`).join('')}</select><button class="primary" data-action="compare" ${state.busy?'disabled':''}>${state.busy?'Comparing…':'Compare plans'}</button></div><p class="note">${p.question}</p>${c?`<div class="insight"><h3>${c.equivalent?'✓ Same result verified':'Results differ — investigate the semantics'}</h3><p>${c.equivalent?'The queries returned equivalent rows, including duplicates. Now compare their actual SQLite plan details.':'Optimization must preserve the metric and rows before performance is considered.'}</p></div>`:''}<div class="planpair">${p.cases.map((spec,i)=>`<section class="panel lesson"><h3>${spec.label}</h3><pre class="sqlblock">${syntax(spec.query)}</pre>${c?`<h4>Actual EXPLAIN QUERY PLAN</h4>${table(c.outputs[i].plan)}<p class="note">${c.outputs[i].result.values.length} result rows</p>`:'<p class="note">Run the comparison to see the actual access path.</p>'}</section>`).join('')}</div>${state.feedback?`<p class="errorText">${esc(state.feedback.message)}</p>`:''}<div class="insight"><h3>How to evaluate a real workload</h3><p>Preserve results → inspect access paths → measure elapsed time and reads over repeated representative runs → account for write cost and storage. CTEs, views, OR, correlated subqueries, and partitions are not automatically fast or slow.</p></div>`}
function dialects(){return `<h2>Concepts transfer. Syntax needs translation.</h2><p class="note">Executable exercises use SQLite. SQL Server procedures, clustered/columnstore indexes, native partitioning, BULK INSERT, and server error handling require that engine. The app teaches their contracts and trade-offs without simulating server features.</p><div class="scroll dialecttable"><table><thead><tr><th>Concept</th><th>SQLite · runs here</th><th>SQL Server / T-SQL</th><th>PostgreSQL</th></tr></thead><tbody>${dialectGuide.map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h3 class="labheading">Sources & attribution</h3><p class="note">The course extension follows your supplied notes about Data With Baraa’s SQL course and warehouse project. The app’s datasets, exercises, and warehouse project are original synthetic teaching material; the original course assets were not imported.</p><ul>${sourceLinks.map(([title,url])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${esc(title)}</a></li>`).join('')}</ul><div class="insight"><h3>Useful distinctions</h3><p>A row calculation preserves rows. GROUP BY changes grain. A window adds analytical context. A CTE names a query step; a normal view stores a definition; a temporary table materializes rows. Performance depends on the resulting plan and workload.</p></div>`}

function warehouseProject(){const n=warehouseMap[state.warehouseNode],tab=state.warehouseTab;return `<div class="courseintro"><div><h2>A warehouse you can reason about.</h2><p>Original CRM + ERP teaching project. Follow requirements → raw evidence → quality rules → business model → reports.</p></div><button class="primary" data-action="lesson" data-id="76" data-case="4">Start guided project →</button></div><div class="tabs"><button data-action="warehousetab" data-tab="map" class="${tab==='map'?'active':''}">Architecture & lineage</button><button data-action="warehousetab" data-tab="catalog" class="${tab==='catalog'?'active':''}">Data catalog</button><button data-action="warehousetab" data-tab="runbook" class="${tab==='runbook'?'active':''}">Load & recovery</button></div>${tab==='map'?`<div class="warehouseflow" role="group" aria-label="Select a warehouse layer">${Object.entries(warehouseMap).map(([key,v],i)=>`<button data-action="warehousenode" data-node="${key}" aria-pressed="${key===state.warehouseNode}" class="${key===state.warehouseNode?'active':''}"><small>0${i+1}</small><strong>${esc(v.title)}</strong></button>`).join('')}</div><section class="panel lesson warehouse-detail"><div class="meta">Selected layer · ${esc(state.warehouseNode)}</div><h2>${esc(n.title)}</h2><p>${esc(n.body)}</p><h3>Inspect the contract</h3><p class="note">${esc(n.table)}</p><div class="fields">${schemas[n.table].map(esc).join('\n')}</div><button class="outline" data-action="lesson" data-id="${n.lesson}" data-case="4">Practice this layer →</button></section><div class="lineagecards">${[['Gender','crm_people.gender + erp_people.gender','Normalize codes → meaningful CRM first → ERP fallback → Unknown'],['Country','erp_locations.country_code','Normalize customer key → map code → integrated customer → country report'],['Sales','bronze_sales.quantity + dim_product.price','Validate line → stable dimension lookup → explicit quantity × price measure']].map(([title,source,rule])=>`<section class="panel lesson"><h3>${title}</h3><p class="note">${source}</p><p>${rule}</p></section>`).join('')}</div>`:tab==='catalog'?`<section class="panel lesson"><h2>Every field has a contract.</h2><p>These are documented target objects you build in the capstone, not hidden materialized outputs. Query warehouse_catalog in the Playground to inspect the same metadata.</p><div class="scroll" tabindex="0" role="region" aria-label="Query results"><table><thead><tr><th>Target field</th><th>Meaning / grain</th><th>Source</th><th>Rule</th></tr></thead><tbody>${[['integrated_customers.customer_id','One customer natural key','crm_people.customer_id','Trim; latest updated_at then source_row'],['integrated_customers.gender','Resolved descriptive attribute','CRM + ERP gender','Meaningful CRM first; ERP fallback'],['integrated_customers.country','Country display name','erp_locations.country_code','Normalize key; map codes'],['integrated_customers.birth_date','Validated birth date','erp_people.birth_date','Calendar-valid; not future at 2025-04-01'],['built_sales.sale_key','One sales line','bronze_sales.row_id','Unique source row identity'],['built_sales.customer_key','Stable dimension key','dim_customer.customer_key','Natural-key lookup; matching customer required'],['built_sales.sales','Teaching sales measure','quantity × catalog price','Positive numeric quantity; rule requires business approval']].map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><button class="outline" data-action="lesson" data-id="87" data-case="4">Build the documented outputs →</button></section>`:`<div class="lineagecards">${[['Before loading','Agree on source counts, formats, source authority, key uniqueness, fact grain, latest versus historical requirements, and blocking quality rules.',76],['Before publishing','Reconcile accepted + rejected counts. Test uniqueness, calendar validity, dimension lookups and business measures. Validate the stage before transactional replacement.',81],['After failure','Rollback replacement writes and retain the earlier snapshot. Log the affected source/run and reject reasons. Replay only under an idempotent contract; checkpoint with the committed load.',85]].map(([title,body,id])=>`<section class="panel lesson"><h3>${title}</h3><p>${body}</p><button class="textbutton" data-action="lesson" data-id="${id}" data-case="4">Try the exercise →</button></section>`).join('')}</div><section class="panel lesson warehouse-detail"><h3>Know the boundary of the demo</h3><p>The foundation is a latest-state batch warehouse. Separate labs demonstrate incremental UPSERT, historical as-of queries and rollback. No live CSV ingestion, SQL Server stored procedures, cloud orchestration, CDC or automated enterprise monitoring is running here. The engine is SQLite and every write execution starts fresh.</p><p class="note">For an Azure implementation, the same contracts can guide ADF ingestion and orchestration, persisted dimensions, and Synapse or Databricks transformations. Platform syntax, governance and operational controls require their own implementation.</p></section>`}`;}
